from decimal import Decimal
import re


_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")
_MAX_AMOUNT = Decimal("1000000.00")


def parse_amount(value):
    """Return a positive amount in exact cents, without context-dependent rounding."""
    if isinstance(value, bool):
        raise ValueError("Invalid amount type")
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, str) and _PLAIN_DECIMAL.fullmatch(value):
        amount = Decimal(value)
    else:
        raise ValueError("Invalid amount type or decimal string")

    if not amount.is_finite() or amount <= 0 or amount > _MAX_AMOUNT:
        raise ValueError("Amount must be positive and at most 1000000.00")

    # Work on the exact coefficient rather than quantizing: quantize can round
    # and depends on the caller's precision, exponent limits, and traps.
    _, digits, exponent = amount.as_tuple()
    shift = exponent + 2
    if shift < 0:
        cutoff = len(digits) + shift
        if cutoff <= 0 or any(digits[cutoff:]):
            raise ValueError("Amount must be exactly representable in cents")
        digits = digits[:cutoff]
    else:
        digits = digits + (0,) * shift
    return Decimal((0, digits, -2))


def format_amount(value):
    return format(value, ".2f")
